package it.eng.allerter.model.impl;

import it.eng.allerter.model.SMS;
import it.eng.allerter.service.SMSLocalServiceUtil;

/**
 * The extended model base implementation for the SMS service. Represents a row in the &quot;ALLERTER_SMS&quot; database table, with each column mapped to a property of this class.
 *
 * <p>
 * This class exists only as a container for the default extended model level methods generated by ServiceBuilder. Helper methods and all application logic should be put in {@link SMSImpl}.
 * </p>
 *
 * @author GFAVINI
 * @see SMSImpl
 * @see SMS
 * @generated
 */
public abstract class SMSBaseImpl extends SMSModelImpl implements SMS {

	/*
	 * NOTE FOR DEVELOPERS:
	 *
	 * Never modify or reference this class directly. All methods that expect a sms model instance should use the <code>SMS</code> interface instead.
	 */
	@Override
	public void persist() {
		if (this.isNew()) {
			SMSLocalServiceUtil.addSMS(this);
		}
		else {
			SMSLocalServiceUtil.updateSMS(this);
		}
	}

}